		{"black avoids poisoned pawn", "3q2k1/8/8/8/3P4/8/8/3R2K1 b - - 0 1", 3},
		{"capture and recapture", "r6k/q7/8/8/8/8/8/R6K w - - 0 1", -5},
		{"en passant", "k7/8/8/3pP3/8/8/8/7K w - d6 0 1", 1},
