		{"capture promotion", "r6k/1P6/8/8/8/8/8/7K w - - 0 1", 9},
		{"rook promotion avoids stalemate", "8/k1P5/2K5/8/8/8/8/8 w - - 0 1", 5},
		{"quiet king evasions lose queen", "k6r/p7/8/8/8/8/1b6/Q6K w - - 0 1", -9},
