	game, err := parsePosition(strings.Fields("fen 7r/8/8/8/8/6k1/8/6BK w - - 0 1"))
	if err != nil {
		t.Fatal(err)
	}
	position := game.Position()
	moves := position.ValidMoves()
	if len(moves) != 1 || moves[0].String() != "g1h2" {
		t.Fatal("fixture must force Bh2")
